    pub static mut edit_backtrack: ::std::os::raw::c_int;
    #[doc = "  @brief Contains the two aligned structures after a call to one of the distance\n  functions with #edit_backtrack set to 1."]
    pub static mut aligned_line: [*mut ::std::os::raw::c_char; 4usize];
